<script setup lang="ts">
import {t as tr} from "../i18n";
import {computed,ref} from 'vue';import {copySpec,changeTemplate,type ScheduledSpec} from '../business/scheduled-form';import params from '@shared/scheduled-params.json';import {useBusinessStore} from '../stores/business';
const spec=defineModel<ScheduledSpec>({required:true}),props=defineProps<{templates:Record<string,string>;busy?:boolean;editing?:boolean;stepwise?:boolean}>(),emit=defineEmits<{preview:[];cancel:[]}>(),business=useBusinessStore(),warning=ref(''),step=ref(1),applicable=params as Record<string,string[]>;
const has=(key:string)=>applicable[spec.value.kind]?.includes(key),trigger=computed(()=>String(spec.value.trigger.type));
function setTemplate(event:Event){const kind=(event.target as HTMLSelectElement).value,result=changeTemplate(spec.value,kind,applicable);spec.value=result.spec;warning.value=result.removed.length?'模板已改变，不适用的参数已移除：'+result.removed.join('、')+'。请核对预览差异。':'';}
function setTrigger(event:Event){const type=(event.target as HTMLSelectElement).value,previous=spec.value.trigger;spec.value={...copySpec(spec.value),trigger:type==='once'?{type,at:previous.at||''}:type==='weekly'?{type,time:previous.time||'20:30',weekdays:previous.weekdays||[1]}:type==='duty'?{type,minutesBefore:previous.minutesBefore??30}:type==='cron'?{type,expression:previous.expression||'30 20 * * *'}:{type,time:previous.time||'20:30'}};}
const once=computed({get:()=>spec.value.trigger.at?new Date(String(spec.value.trigger.at)).toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).replace(' ','T').slice(0,16):'',set:v=>spec.value.trigger.at=v+':00+08:00'});
const inbox=computed({get:()=>spec.value.approvedEffects.includes('inbox'),set:yes=>spec.value.approvedEffects=yes?['report','inbox']:['report']});
const recipientKind=computed({get:()=>spec.value.recipients.length===1?spec.value.recipients[0]?.kind||'user':'existing',set:kind=>{if(kind==='existing')return;spec.value.recipients=[kind==='user'?{kind,userId:business.profile?.username||''}:kind==='role'?{kind,role:'volunteer'}:{kind,className:''}];}});
const recipientValue=computed({get:()=>{const r=spec.value.recipients[0]||{};return r.userId||r.role||r.className||'';},set:value=>{const r=spec.value.recipients[0];if(r)r[r.kind==='role'?'role':r.kind==='class'?'className':'userId']=value;}});
function setParam(key:string,event:Event,numeric=false){const value=(event.target as HTMLInputElement).value;if(value==='')delete spec.value.params[key];else spec.value.params[key]=numeric?Number(value):value;}
</script>
<template><form class="jobs-form" :novalidate="stepwise" @submit.prevent="emit('preview')"><h3>{{tr(editing?'修改规则':'新增规则')}}</h3><ol v-if="stepwise" class="jobs-steps" :aria-label="tr('规则设置步骤')"><li v-for="(label,index) in ['模板','时间与校历','参数范围','接收人与效果']" :key="label"><button type="button" :aria-current="step===index+1?'step':undefined" @click="step=index+1">{{index+1}} {{label}}</button></li></ol><p v-if="warning" class="mobile-warning">{{warning}}</p><div v-show="!stepwise||step===1" class="jobs-form-step"><label>{{tr("模板")}}<select :aria-label="tr('模板')" :value="spec.kind" @change="setTemplate"><option v-for="(label,key) in templates" :key="key" :value="key">{{label}}</option></select></label><label>{{tr("名称")}}<input v-model="spec.name" maxlength="120" :placeholder="tr('留空使用模板名称')"></label></div><div v-show="!stepwise||step===2" class="jobs-form-step"><label>{{tr("触发方式")}}<select :value="trigger" :aria-label="tr('触发方式')" @change="setTrigger"><option value="daily">{{tr("每天")}}</option><option value="weekly">{{tr("每周")}}</option><option value="once">{{tr("指定时间")}}</option><option value="cron">{{tr("高级 Cron（受限）")}}</option><option v-if="spec.kind==='duty_reminder'" value="duty">{{tr("正式班次前")}}</option></select></label><label v-if="trigger==='daily'||trigger==='weekly'">{{tr("北京时间")}}<input v-model="spec.trigger.time" type="time" required></label><label v-if="trigger==='weekly'">{{tr("星期")}}<select v-model="spec.trigger.weekdays" multiple><option v-for="(day,i) in ['周日','周一','周二','周三','周四','周五','周六']" :key="i" :value="i">{{day}}</option></select></label><label v-if="trigger==='once'">{{tr("北京时间")}}<input v-model="once" type="datetime-local" required></label><label v-if="trigger==='cron'">{{tr("高级 Cron（分 时 * * 星期）")}}<input v-model="spec.trigger.expression" required maxlength="40"></label><label v-if="trigger==='duty'">{{tr("提前分钟")}}<input v-model.number="spec.trigger.minutesBefore" type="number" min="0" max="120"></label><label>{{tr("校历策略")}}<select v-model="spec.calendarPolicy"><option value="all_days">{{tr("每天 / 正式班次日期")}}</option><option value="teaching_days">{{tr("仅校历确认的教学日")}}</option></select></label></div><div v-show="!stepwise||step===3" class="jobs-form-step"><label v-if="has('roomId')">{{tr("房间编号（留空不限）")}}<input :value="spec.params.roomId" maxlength="100" @input="setParam('roomId',$event)"></label><label v-if="has('className')">{{tr("班级名称（留空按授权范围）")}}<input :value="spec.params.className" maxlength="100" @input="setParam('className',$event)"></label><label v-if="has('thresholdHours')">{{tr("人工授权处理时限（小时，可留空仅按 dueAt）")}}<input :value="spec.params.thresholdHours" type="number" min="1" max="720" @input="setParam('thresholdHours',$event,true)"></label><label>{{tr("允许停机补跑窗口（小时，默认 6）")}}<input :value="spec.params.maxMissedHours" type="number" min="1" max="24" @input="setParam('maxMissedHours',$event,true)"></label></div><div v-show="!stepwise||step===4" class="jobs-form-step"><label>{{tr("接收范围")}}<select v-model="recipientKind" :aria-label="tr('接收范围')"><option value="user">{{tr("本人 / 指定账号")}}</option><option v-if="spec.recipients.length>1" value="existing">{{tr("保留原对象（多项）")}}</option><template v-if="business.profile?.identity==='admin'"><option value="class">{{tr("班级")}}</option><option value="role">{{tr("角色")}}</option></template></select></label><label v-if="business.profile?.identity==='admin'&&recipientKind!=='existing'">{{tr("账号 / 班级 / 角色")}}<input v-model="recipientValue" required></label><p>{{tr("当前接收对象：")}}{{tr(spec.recipients.map(r=>r.kind==='user'?r.userId:r.kind==='class'?'班级 '+r.className:'角色 '+({admin:'管理员',volunteer:'志愿者',student:'学生'} as Record<string,string>)[r.role]).join('、'))}}</p><label class="jobs-check"><input v-model="inbox" type="checkbox">{{tr("保存结果并发送站内提醒")}}</label></div><div v-if="stepwise" class="mobile-actions"><button v-if="step>1" type="button" @click="step--">{{tr("上一步")}}</button><button v-if="step<4" type="button" @click="step++">{{tr("下一步")}}</button></div><button v-if="!stepwise||step===4" :disabled="busy">{{tr("预览未来时间和样例")}}</button><button type="button" @click="emit('cancel')">{{tr("取消")}}{{tr(editing?'修改':'新增')}}</button></form></template>

<style scoped>.jobs-form-step{display:contents}.jobs-steps{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;grid-column:1/-1}.jobs-steps button{width:100%;font-size:calc(var(--ui-font-size) * 1.0)}.jobs-steps button[aria-current="step"]{background:var(--text);color:var(--surface)}.jobs-form>.mobile-actions{grid-column:1/-1}</style>
